+    scrollSpeed = 210 + lv * 42 + elapsed * 1.6;      // px/s, escalates
+    gateGap = Math.max(108, 178 - lv * 14);            // narrows
+    gateSpacing = Math.max(190, 265 - lv * 12);        // denser
+  }
+
