+    packages.push({
+      x: 70 + Math.random() * (W - 140),
+      y, baseX: 0, r: 13,
+      bob: Math.random() * Math.PI * 2,
+      taken: false,
+      hue: [45, 300, 140, 200][Math.floor(Math.random() * 4)],
