        ctx.strokeStyle = side === 0 ? "#39e6ff" : "#ff4ecd";
        ctx.lineWidth = 3;
        ctx.shadowColor = ctx.strokeStyle; ctx.shadowBlur = 12;
        ctx.beginPath();
        for (let y = -20; y <= H + 20; y += 18) {
          const e = wallEdge(side, y, wallPhase);
          if (y === -20) ctx.moveTo(e, y); else ctx.lineTo(e, y);
          rimX.push(e);
        }
        ctx.stroke();
        ctx.shadowBlur = 0;
      }
    }

