  score: document.getElementById("score").textContent,
  time: document.getElementById("time").textContent,
  lives: document.getElementById("lives").textContent,
  combo: document.getElementById("combo").textContent,
}));
console.log("HUD:", JSON.stringify(hud));
await page.screenshot({ path: "screenshots/gameplay.png" });
// force game-over screen to verify restart flow visuals
await page.evaluate(() => document.getElementById("retryBtn").click());
await new Promise(r => setTimeout(r, 300));
// simulate crash: directly exhaust by evaluating endGame? Instead check over screen hidden logic via timeout path is slow; just verify DOM flow exists
console.log("ERRORS:", errors.length ? errors.join("|") : "none");
await browser.close();
EOF
